-- DEC-06 additive only; run solely against an explicitly selected disposable test_* target.
CREATE TABLE payment_images (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,restaurant_id BIGINT NOT NULL,uploader_id BIGINT NOT NULL,order_id BIGINT NULL,kind VARCHAR(16) NOT NULL,object_key VARCHAR(200) NOT NULL UNIQUE,content_hash CHAR(64) NOT NULL,mime_type VARCHAR(32) NOT NULL,size_bytes INT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deletion_requested_at DATETIME(3) NULL,deleted_at DATETIME(3) NULL,
 FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(uploader_id) REFERENCES accounts(id),FOREIGN KEY(order_id,restaurant_id) REFERENCES orders(id,restaurant_id),CHECK(kind IN ('qr','receipt','refund')),CHECK(size_bytes BETWEEN 1 AND 5242880),CHECK(mime_type IN ('image/png','image/jpeg')),INDEX(restaurant_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_qr_proposals (
 qr_version INT UNSIGNED NULL, id BIGINT AUTO_INCREMENT PRIMARY KEY,restaurant_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,bank_code VARCHAR(32) NOT NULL,bank_name VARCHAR(200) NOT NULL,account_number VARCHAR(64) NOT NULL,account_name VARCHAR(200) NOT NULL,qr_image_id BIGINT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',version INT UNSIGNED NOT NULL DEFAULT 1,reviewed_by BIGINT NULL,reason VARCHAR(1000) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(actor_id) REFERENCES accounts(id),FOREIGN KEY(reviewed_by) REFERENCES accounts(id),FOREIGN KEY(qr_image_id) REFERENCES payment_images(id),CHECK(status IN ('pending','approved','rejected','suspended')),CHECK(version BETWEEN 1 AND 2147483647),INDEX(restaurant_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_qr_config (
 restaurant_id BIGINT PRIMARY KEY,active_id BIGINT NULL,version INT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(active_id) REFERENCES payment_qr_proposals(id),CHECK(version<=2147483647)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_instructions (
 order_id BIGINT PRIMARY KEY,restaurant_id BIGINT NOT NULL,qr_version INT UNSIGNED NOT NULL,proposal_id BIGINT NOT NULL,qr_image_id BIGINT NOT NULL,bank_code VARCHAR(32) NOT NULL,bank_name VARCHAR(200) NOT NULL,account_number VARCHAR(64) NOT NULL,account_name VARCHAR(200) NOT NULL,amount_vnd BIGINT NOT NULL,reference VARCHAR(32) NOT NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(order_id,restaurant_id) REFERENCES orders(id,restaurant_id),FOREIGN KEY(proposal_id) REFERENCES payment_qr_proposals(id),FOREIGN KEY(qr_image_id) REFERENCES payment_images(id),CHECK(amount_vnd BETWEEN 0 AND 1000000000000),CHECK(qr_version BETWEEN 1 AND 2147483647)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_receipts (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,transaction_hash CHAR(64) NOT NULL UNIQUE,event_hash CHAR(64) NOT NULL,transaction_reference VARCHAR(255) NOT NULL,amount_vnd BIGINT NOT NULL,received_at DATETIME(3) NOT NULL,observed_reference VARCHAR(255) NOT NULL,instruction_version INT UNSIGNED NOT NULL,classification VARCHAR(32) NOT NULL,evidence_id BIGINT NOT NULL UNIQUE,actor_id BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(evidence_id) REFERENCES payment_images(id),FOREIGN KEY(actor_id) REFERENCES accounts(id),CHECK(amount_vnd>0),CHECK(instruction_version BETWEEN 1 AND 2147483647),CHECK(classification IN ('matched','wrong_amount','wrong_reference','duplicate','late')),INDEX(order_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_refunds (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,receipt_id BIGINT NOT NULL UNIQUE,amount_vnd BIGINT NOT NULL,reason VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',due_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),refunded_at DATETIME(3) NULL,recorded_at DATETIME(3) NULL,actor_id BIGINT NULL,evidence_id BIGINT NULL UNIQUE,transaction_reference VARCHAR(255) NULL,transaction_hash CHAR(64) NULL UNIQUE,event_hash CHAR(64) NULL,
 FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(receipt_id) REFERENCES payment_receipts(id),FOREIGN KEY(actor_id) REFERENCES accounts(id),FOREIGN KEY(evidence_id) REFERENCES payment_images(id),CHECK(amount_vnd>0),CHECK(status IN ('pending','refunded')),CHECK((status='pending' AND refunded_at IS NULL AND actor_id IS NULL AND evidence_id IS NULL AND transaction_hash IS NULL AND event_hash IS NULL AND recorded_at IS NULL AND transaction_reference IS NULL) OR (status='refunded' AND refunded_at IS NOT NULL AND actor_id IS NOT NULL AND evidence_id IS NOT NULL AND transaction_hash IS NOT NULL AND event_hash IS NOT NULL AND recorded_at IS NOT NULL AND transaction_reference IS NOT NULL)),INDEX(order_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_claims (
 order_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL,instruction_version INT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(actor_id) REFERENCES accounts(id),CHECK(instruction_version BETWEEN 1 AND 2147483647)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE payment_disputes (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,receipt_id BIGINT NULL,refund_id BIGINT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'open',version INT UNSIGNED NOT NULL DEFAULT 1,resolution_note VARCHAR(1000) NULL,resolved_by BIGINT NULL,resolved_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(actor_id) REFERENCES accounts(id),FOREIGN KEY(receipt_id) REFERENCES payment_receipts(id),FOREIGN KEY(refund_id) REFERENCES payment_refunds(id),FOREIGN KEY(resolved_by) REFERENCES accounts(id),CHECK(status IN ('open','resolved')),CHECK(version BETWEEN 1 AND 2147483647),CHECK((status='open' AND resolved_at IS NULL AND resolved_by IS NULL AND resolution_note IS NULL) OR(status='resolved' AND resolved_at IS NOT NULL AND resolved_by IS NOT NULL AND resolution_note IS NOT NULL)),INDEX(order_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
